use std::path::PathBuf;

use callisto_model::vcs::GitAccess;
use callisto_model::{CommitSha, Package, Severity, Version};

use crate::config::PreMajorInferencePolicy;
use crate::error::GraphError;

pub trait SeverityInference: Send + Sync {
    /// `git` is the caller's already-discovered [`GitAccess`] (e.g.
    /// `aggregate()`'s own parameter, itself `Workspace`-shared) -- an impl
    /// that needs commit history must use this rather than discovering its
    /// own, so an N-package workspace pays for one discovery, not N.
    fn infer(
        &self,
        pkg: &Package,
        git: &GitAccess<'_>,
        window: InferenceWindowSpec<'_>,
    ) -> Result<Option<InferenceOutcome>, GraphError>;

    /// Whether `infer` reads commit history: when it doesn't, neither its window nor full history is worked out.
    fn reads_history(&self) -> bool {
        true
    }
}

pub struct InferenceWindowSpec<'a> {
    pub pathspecs: &'a [PathBuf],
    pub since: Option<CommitSha>,
    pub current_version: &'a Version,
    pub has_prior_release: bool,
    pub policy: PreMajorInferencePolicy,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InferenceOutcome {
    pub severity: Severity,
    pub commit_count: usize,
    pub remapped: bool,
    pub commits: Vec<(CommitSha, String)>,
}

pub struct NoInference;

impl SeverityInference for NoInference {
    fn infer(
        &self,
        _pkg: &Package,
        _git: &GitAccess<'_>,
        _window: InferenceWindowSpec<'_>,
    ) -> Result<Option<InferenceOutcome>, GraphError> {
        Ok(None)
    }

    fn reads_history(&self) -> bool {
        false
    }
}

/// The shipped impl. A thin, stateless adapter over
/// `crate::conventional::infer_severity` -- it holds no fields of its own; the caller's
/// [`GitAccess`] is handed in per call via [`SeverityInference::infer`]'s `git` parameter
/// rather than discovered here, so this type carries nothing to discover it with.
pub struct CommitInference;

impl SeverityInference for CommitInference {
    fn infer(
        &self,
        _pkg: &Package,
        git: &GitAccess<'_>,
----
/// entire history on every `aggregate()`-driven command.
///
/// A tag that is listed but does not resolve to a commit is an error: guessing "infer over full history" would
/// plan a bump from commits the last release already covered.
fn resolve_since(git: &GitAccess<'_>, tags: &TagIndex, tag_name: &str) -> Result<CommitSha, GraphError> {
    tags.commit_of(git, tag_name)?.ok_or_else(|| {
        GraphError::Vcs(callisto_model::vcs::VcsError::RefNotFound {
            ref_name: tag_name.to_string(),
        })
    })
}

/// Resolves a changeset entry's or `--package` argument's parsed `PackageId`
/// against the packages in the graph, through [`IdentityIndex::resolve_id`] --
/// the one selector resolver, not a `PackageId::matches` scan (which treats a
/// Bare query as an ecosystem wildcard and would wrongly let a qualified
/// selector for one ecosystem select a same-named package in another).
///
/// `Ok(None)`: no match (unknown package, reported separately by
/// `status`). `Ok(Some(pkg))`: unambiguous. `Err(AmbiguousName)`: two or
/// more matches (E103).
pub(crate) fn resolve_target_package<'a>(
    packages: impl Iterator<Item = &'a Package>,
    identity: &IdentityIndex,
    id: &PackageId,
) -> Result<Option<&'a Package>, GraphError> {
    match identity.resolve_id(id) {
